@startuml

class Sober {
}

class Car {
  + LicensePlate : string
}

class Owner {
  + Name : string
}

class Accident {
  + Date : date
  + Location : string
  + DamageAmount : float
}

class RideHail {
  + PickUpTime : datetime
  + DropOffTime : datetime
  + PickUpLocation : string
  + DropOffLocation : string
  + Duration : string
  + Distance : float
  + PassengerCount : int
  + Fee : float
  + RequestType : string
}

class RideShare {
  + PickUpTime : datetime
  + DropOffTime : datetime
  + PickUpLocation : string
  + DropOffLocation : string
  + Duration : string
  + Distance : float
  + UpfrontFee : float
}

class Customer {
  + Name : string
}

class RideHailCustomer {
  + Name : string
}

class RideShareCustomer {
  + Name : string
}

class CarOwner extends Owner {}

Car "1" -- "0..*" Accident : experiences
Car "0..*" -- "0..1" Owner : owned by
Car "1" -- "0..*" RideHail : provides
Car "1" -- "0..*" RideShare : provides
RideHail "0..*" -- "1" RideHailCustomer : lead customer
RideShare "0..*" -- "1..10" RideShareCustomer : passengers

@enduml

